#include "ramond/direct_pbw.hpp"
#include "ramond/branching.hpp"
#include <iostream>
#include <iomanip>
using namespace ramond;
using S=Machine;
using Coeff=std::array<S,8>;
using Lev=std::array<int,3>;
using GlassesSeries=std::map<Lev,Coeff>;
struct Edge{std::vector<int> states;std::vector<S> inv;};
class Physical{
 ScaWords<S>w;std::array<std::unique_ptr<ScaModule<S>>,3>gm,wm;std::array<std::unique_ptr<ScaWard<S>>,2>v;std::map<Lev,Edge> es;int f;
 const Edge&edge(int slot,int level2,int parity){Lev key{slot,level2,parity};if(es.count(key))return es.at(key);Edge e;int level=slot?level2/2:level2;
 for(int l=0;l<=(slot?level:level/2);l++)for(auto ls:partitions(l))for(auto gs:partitions(level-(slot?l:2*l),true,!slot)){ScaWord word;for(int n:ls)word.push_back({0,-2*n});for(int n:gs)word.push_back({1,slot?-2*n:-n});int id=w.intern(word),g=slot?(parity+gs.size())%2:0;if((w.words[id].parity+g)%2==parity)e.states.push_back(2*id+g);}
 int n=e.states.size();std::vector<S>gram(n*n);for(int i=0;i<n;i++)for(int j=0;j<n;j++)gram[i*n+j]=gm[slot]->inner(e.states[i],e.states[j]);e.inv=pbw_inverse(gram,n);return es.emplace(key,e).first->second;}
 public:Physical(S b,std::array<S,3>p,int ff,int el,int er):f(ff){S q=b+S(1)/b,c=S(1.5)+S(3)*q*q;for(int j=0;j<3;j++){S h=q*q/S(8)-p[j]*p[j]/S(2)+(j?S(1./16):S(0));gm[j]=std::make_unique<ScaModule<S>>(w,h,c,p[j]/root(S(2)),j,true);wm[j]=std::make_unique<ScaModule<S>>(w,h,c,p[j]/root(S(2)),j,false);}v[0]=std::make_unique<ScaWard<S>>(w,std::array<ScaModule<S>*,3>{wm[0].get(),wm[1].get(),wm[1].get()},0,f,el);v[1]=std::make_unique<ScaWard<S>>(w,std::array<ScaModule<S>*,3>{wm[0].get(),wm[2].get(),wm[2].get()},0,f,er);}
 S trace(int bridge2,int loop2,int parity,int side){auto&br=edge(0,bridge2,bridge2%2);auto&e=edge(side+1,loop2,parity);require(br.states.size()==1,"export supports one-dimensional bridge levels");S ans=0;for(int i=0;i<int(e.states.size());i++)for(int j=0;j<int(e.states.size());j++){int x=e.states[i],y=e.states[j];S phase=power((S(-1)+S(Machine(0,1)))/root(S(2)),x%2+y%2);ans+=e.inv[i*e.states.size()+j]*phase*v[side]->value({br.states[0],x,y});}return ans;}
 Coeff coefficient(Lev lev){Coeff out{};if(lev[0]%2!=f)return out;auto&br=edge(0,lev[0],f);for(int al=0;al<2;al++)for(int ar=0;ar<2;ar++){std::array<const Edge*,2>loop{&edge(1,lev[1],al),&edge(2,lev[2],ar)};std::array<std::vector<S>,2>t;for(int side=0;side<2;side++){auto&e=*loop[side];t[side].resize(br.states.size());for(int a=0;a<int(br.states.size());a++)for(int i=0;i<int(e.states.size());i++)for(int j=0;j<int(e.states.size());j++){int x=e.states[i],y=e.states[j];S phase=power((S(-1)+S(Machine(0,1)))/root(S(2)),x%2+y%2);t[side][a]+=e.inv[i*e.states.size()+j]*phase*v[side]->value({br.states[a],x,y});}}S ans=0;int d=br.states.size();for(int i=0;i<d;i++)for(int j=0;j<d;j++)ans+=t[0][i]*br.inv[i*d+j]*t[1][j];out[f|(al<<1)|(ar<<2)]=ans;}return out;}
};
S norm(S h,int n){return n?S(2)*h:S(1);}
S rho(int i,int j,int k,std::array<S,3>h){S ans=0;for(int p=0;p<=std::min(i,k);p++){S term=S(binomial(i,p))*rising(S(2)*h[2]+S(k-p),p);for(int t=0;t<p;t++)term*=S(k-t);term*=rising(h[2]+h[1]-h[0],k-p)*rising(h[0]+h[1]-h[2]+S(-k+p),i-p);ans+=term;}return ans*rising(h[0]-h[1]-h[2]+S(i-j+1-k),j);}
class DV{S b;std::array<S,3>p;int f,el,er,il,ir;LowAnchors<S>left,right;RamondActions<S>la,ra;MiddleBranching<S>lm,rm;
 S copy(int cp,int nb,int li,int lo,int ri,int ro,std::array<int,5>d){S hb=branch_weight(cp,nb,b,p[0]),hli=branch_weight(cp,li,b,p[1]),hlo=branch_weight(cp,lo,b,p[1]),hri=branch_weight(cp,ri,b,p[2]),hro=branch_weight(cp,ro,b,p[2]);S val=rho(d[0],d[1],d[2],{hb,hli,hlo})*rho(d[0],d[3],d[4],{hb,hri,hro})/norm(hb,d[0]);S ext=cp?(b*b+S(2))/(S(2)*(S(1)-b*b)):-(S(1)+S(2)*b*b)/(S(2)*(S(1)-b*b));if(il)val*=rho(d[2],0,d[1],{hlo,ext,hli})/(norm(hli,d[1])*norm(hlo,d[2]));else{if(d[1]!=d[2])return 0;val/=norm(hli,d[1]);}if(ir)val*=rho(d[4],0,d[3],{hro,ext,hri})/(norm(hri,d[3])*norm(hro,d[4]));else{if(d[3]!=d[4])return 0;val/=norm(hri,d[3]);}return val;}
 public:DV(S bb,std::array<S,3>pp,int ff,int ee,int rr,int ii,int jj):b(bb),p(pp),f(ff),el(ee),er(rr),il(ii),ir(jj),left(b,{p[0],p[1],p[1]},0),right(b,{p[0],p[2],p[2]},0),la(b,p[1],false),ra(b,p[2],false),lm(b,p[1],la),rm(b,p[2],ra){}
 Coeff coefficient(Lev lev){return full({lev[0],lev[1],lev[1],lev[2],lev[2]});}
 Coeff full(std::array<int,5>lev){Coeff out{};for(int nb:{-2,0,2}){if(((nb/2)%2+2)%2!=f)continue;int db2=lev[0]-nb*nb/4;if(db2<0||db2%2)continue;for(int li:{-3,-1,1,3})for(int lo:{-3,-1,1,3}){if(il?std::abs(li-lo)!=2:li!=lo)continue;int dli=lev[1]/2-ramond_level(li),dlo=lev[2]/2-ramond_level(lo);if(std::min(dli,dlo)<0)continue;for(int ri:{-3,-1,1,3})for(int ro:{-3,-1,1,3}){if(ir?std::abs(ri-ro)!=2:ri!=ro)continue;int dri=lev[3]/2-ramond_level(ri),dro=lev[4]/2-ramond_level(ro);if(std::min(dri,dro)<0)continue;std::array<int,5>ds{db2/2,dli,dlo,dri,dro};S vir=0;for(int mask=0;mask<32;mask++){std::array<int,5>x,y;bool ok=true;for(int e=0;e<5;e++){x[e]=(mask>>e)&1;y[e]=ds[e]-x[e];if(y[e]<0||y[e]>1)ok=false;}if(ok)vir+=copy(0,nb,li,lo,ri,ro,x)*copy(1,nb,li,lo,ri,ro,y);}for(int al=0;al<2;al++)for(int ar=0;ar<2;ar++){S val=left.raw({nb,li,lo},al,al,sign(f)*el)*right.raw({nb,ri,ro},ar,ar,sign(f)*er)*S(sign(nb/2))*vir/ns_norm(nb,b,p[0])/r_norm(li,al,b,p[1])/r_norm(ri,ar,b,p[2]);if(il)val*=lm.raw(lo,li,al)/r_norm(lo,al,b,p[1]);if(ir)val*=rm.raw(ro,ri,ar)/r_norm(ro,ar,b,p[2]);out[f|(al<<1)|(ar<<2)]+=val;}}}}return out;}
};
Coeff fermion(Lev lev,S q,int il,int ir){Coeff out{};if(lev[0])return out;FermionForm ff;for(int gl=0;gl<2;gl++)for(int gr=0;gr<2;gr++){AuxState a{},l{lev[1]?Part{1}:Part{},gl},r{lev[2]?Part{1}:Part{},gr};int pl=aux_parity(1,l),pr=aux_parity(1,r);S x=ff.complex_value<S>({a,l,l})*ff.complex_value<S>({a,r,r})*S(sign(pl+pr));if(il)x*=q/root(S(2))*S(sign(gl));if(ir)x*=q/root(S(2))*S(sign(gr));out[(pl<<1)|(pr<<2)]+=x;}return out;}

S product_entry(const Coeff&ph,const Coeff&ff,int f,int target){S v=0;for(int x=0;x<8;x++)for(int y=0;y<8;y++)if((x^y)==target){int exponent=(((x>>1)&1)*((y>>1)&1)+((x>>2)&1)*((y>>2)&1)+f*(((x>>1)&1)+((x>>2)&1)));v+=S(sign(exponent))*ph[x]*ff[y];}return v;}
void complex_json(S z){std::cout<<"["<<z.real()<<","<<z.imag()<<"]";}
int glasses_diagonal_main(){S b=1.4;std::array<S,3>p{11./23,13./29,17./31};std::vector<Lev>ls;for(int b2=0;b2<=2;b2++)for(int l2=0;l2<=2;l2+=2)for(int r2=0;r2<=2;r2+=2)ls.push_back({b2,l2,r2});std::sort(ls.begin(),ls.end(),[](Lev a,Lev b){int x=a[0]+a[1]+a[2],y=b[0]+b[1]+b[2];return x==y?a<b:x<y;});
 std::cout<<std::setprecision(17)<<"{\n\"precision\":\"machine complex double\",\"individual_edge_cutoff\":1,\"virasoro_method\":\"exact CCY global term; no edge reaches a level-two pole or Schottky vacuum correction\",\"parameters\":{\"b\":1.4,\"P_B\":\"11/23\",\"P_L\":\"13/29\",\"P_R\":\"17/31\"},\"cases\":[\n";
 bool firstcase=true;double start=seconds();int failures=0;for(int f=0;f<2;f++)for(int el:{-1,1})for(int er:{-1,1}){double tick=seconds();int il=sign(f)*el<0,ir=sign(f)*er<0;Physical phy(b,p,f,el,er);DV dv(b,p,f,el,er,il,ir),vanilla(b,p,f,el,er,0,0);GlassesSeries physical,aux,numerator,recovered;for(auto lev:ls){physical[lev]=phy.coefficient(lev);aux[lev]=fermion(lev,b+S(1)/b,il,ir);numerator[lev]=dv.coefficient(lev);}double err=0,scaled=0,recerr=0,recscaled=0,zeroerr=0;S K=power((b+S(1)/b)/root(S(2)),il+ir);
 for(auto lev:ls){Coeff expected{};for(auto aa:ls){Lev bb{lev[0]-aa[0],lev[1]-aa[1],lev[2]-aa[2]};auto fa=aux.find(bb);if(fa==aux.end())continue;for(int k=0;k<8;k++)expected[k]+=product_entry(physical[aa],fa->second,f,k);}
 for(int k=0;k<8;k++){double e=std::abs(numerator[lev][k]-expected[k]);err=std::max(err,e);scaled=std::max(scaled,e/std::max({1.,std::abs(numerator[lev][k]),std::abs(expected[k])}));}
 // Recover in the known Ramond-loop sector, using no physical coefficients.
 S leading=numerator[lev][f];for(auto aa:ls){Lev bb{lev[0]-aa[0],lev[1]-aa[1],lev[2]-aa[2]};if(bb==Lev{0,0,0})continue;auto old=recovered.find(aa),ff=aux.find(bb);if(old==recovered.end()||ff==aux.end())continue;leading-=product_entry(old->second,ff->second,f,f);}S amplitude=leading/(S(4)*K);Coeff recovered_here{};for(int al=0;al<2;al++)for(int ar=0;ar<2;ar++)recovered_here[f|(al<<1)|(ar<<2)]=amplitude*power(S(Machine(0,-el)),al)*power(S(Machine(0,-er)),ar);recovered[lev]=recovered_here;
 for(int k=0;k<8;k++){double e=std::abs(recovered_here[k]-physical[lev][k]);recerr=std::max(recerr,e);recscaled=std::max(recscaled,e/std::max({1.,std::abs(recovered_here[k]),std::abs(physical[lev][k])}));}
 if(il||ir){auto z=vanilla.coefficient(lev);for(auto v:z)zeroerr=std::max(zeroerr,std::abs(v));}}
 if(scaled>1e-9||recscaled>1e-9||zeroerr>1e-9)failures++;if(!firstcase)std::cout<<",\n";firstcase=false;std::cout<<"{\"f\":"<<f<<",\"eta_L\":"<<el<<",\"eta_R\":"<<er<<",\"split_loops\":["<<il<<","<<ir<<"],\"components\":"<<8*ls.size()<<",\"numerator_max_absolute_error\":"<<err<<",\"numerator_max_scaled_error\":"<<scaled<<",\"recovery_max_absolute_error\":"<<recerr<<",\"recovery_max_scaled_error\":"<<recscaled<<",\"vanilla_odd_loop_max_absolute\":"<<zeroerr<<",\"elapsed_seconds\":"<<seconds()-tick<<",\"coefficients\":[";bool firstrow=true;for(auto lev:ls){if(!firstrow)std::cout<<",";firstrow=false;std::cout<<"{\"level2\":["<<lev[0]<<","<<lev[1]<<","<<lev[2]<<"],\"pbw\":[";for(int k=0;k<8;k++){if(k)std::cout<<",";complex_json(physical[lev][k]);}std::cout<<"],\"numerator\":[";for(int k=0;k<8;k++){if(k)std::cout<<",";complex_json(numerator[lev][k]);}std::cout<<"],\"recovered\":[";for(int k=0;k<8;k++){if(k)std::cout<<",";complex_json(recovered[lev][k]);}std::cout<<"]}";}std::cout<<"]}";
 }
 std::cout<<"\n],\"runtime_seconds\":"<<seconds()-start<<",\"failed_cases\":"<<failures<<"}\n";return failures?1:0;}
